generated_pydough:
# Find distinct salaries of instructors who earn less than the maximum salary
distinct_salaries = college_2.CALCULATE(
    max_salary=MAX(instructors.salary)
).instructors.WHERE(
    salary < max_salary
).PARTITION(name="salary_groups", by=salary).CALCULATE(
    salary=salary
)

# Calculate the global average number of products across all shops
# Then filter shops above this average and return their names
above_average_shops = employee_hire_evaluation.CALCULATE(
    avg_products=AVG(shops.number_products)
).shops.WHERE(
    number_products > avg_products
).CALCULATE(
    shop_name=name
)

# Find investors with at least 2 SALE transactions
investors_with_multiple_sales = investor.WHERE(
    HAS(transaction) == 1
).CALCULATE(
    investor_id=investor_id,
    investor_details=investor_details,
    sale_transaction_count=COUNT(transaction.WHERE(transaction_type_code == "SALE"))
).WHERE(
    sale_transaction_count >= 2
).CALCULATE(
    investor_id=investor_id,
    investor_details=investor_details
)

# Count drama workshop groups per marketing region and find the one with the most
region_with_most_groups = drama_workshop_group.PARTITION(
    name="regions", 
    by=marketing_region_code
).CALCULATE(
    marketing_region_code=marketing_region_code,
    group_count=COUNT(drama_workshop_group)
).TOP_K(1, by=group_count.DESC()).CALCULATE(
    marketing_region_code=marketing_region_code
)

# Filter professionals living in Hawaii or Wisconsin and get their emails
professionals_in_target_states = professional.WHERE(
    ISIN(state, ("Hawaii", "Wisconsin"))
).CALCULATE(
    email_address=email_address
)

high_membership_visitors = visitors.WHERE(
    level_of_membership > 4
).CALCULATE(
    name=name
).ORDER_BY(level_of_membership.DESC())

artists_without_2004_exhibition = artists.WHERE(
    HASNOT(exhibitions.WHERE(year == '2004')) == 1
).CALCULATE(
    artist_name=name
)

columbus_crew_players_info = teams.WHERE(
    name == "Columbus Crew"
).players.CALCULATE(
    player_name=player,
    years_played=years_played
)

teacher_for_math_course = course_teach.course_arranges.WHERE(
    course.course == 'Math'
).CALCULATE(
    teacher_name=teacher.name
)
